//! Cross-implementation conformance: recompute every vector in
//! shared/test-vectors.json (generated by the JS engine) and compare.
use base64::Engine;
use drawstep_core::analysis::{analyze, AnalyzeOptions, Analysis};
use drawstep_core::geometry::{detect_paper, homography, warp_gray};
use drawstep_core::imgproc::*;
use drawstep_core::project::{Prep, Step};
use drawstep_core::render::{render_style, RenderOptions};
use drawstep_core::shared::shared;
use drawstep_core::steps::generate_steps;
use serde_json::Value;

fn fnv(bytes: &[u8]) -> String {
    let mut h: u32 = 0x811c9dc5;
    for &b in bytes {
        h ^= b as u32;
        h = h.wrapping_mul(0x01000193);
    }
    format!("{h:08x}")
}

fn vectors() -> Value {
    serde_json::from_str(include_str!("../../../../shared/test-vectors.json")).unwrap()
}

fn image(v: &Value) -> Rgba {
    let w = v["image"]["width"].as_u64().unwrap() as usize;
    let h = v["image"]["height"].as_u64().unwrap() as usize;
    let data = base64::engine::general_purpose::STANDARD.decode(v["image"]["rgbaBase64"].as_str().unwrap()).unwrap();
    Rgba { width: w, height: h, data }
}

/// Deep compare JSON with numeric tolerance.
fn close(a: &Value, b: &Value, path: &str) {
    match (a, b) {
        (Value::Number(x), Value::Number(y)) => {
            let (x, y) = (x.as_f64().unwrap(), y.as_f64().unwrap());
            assert!((x - y).abs() <= 2e-4, "{path}: {x} != {y}");
        }
        (Value::Array(x), Value::Array(y)) => {
            assert_eq!(x.len(), y.len(), "{path}: length {} != {}", x.len(), y.len());
            for (i, (p, q)) in x.iter().zip(y).enumerate() {
                close(p, q, &format!("{path}[{i}]"));
            }
        }
        (Value::Object(x), Value::Object(y)) => {
            let mut kx: Vec<_> = x.keys().collect();
            let mut ky: Vec<_> = y.keys().collect();
            kx.sort();
            ky.sort();
            assert_eq!(kx, ky, "{path}: keys differ");
            for k in kx {
                close(&x[k], &y[k], &format!("{path}.{k}"));
            }
        }
        _ => assert_eq!(a, b, "{path}"),
    }
}

#[test]
fn primitives_match_js() {
    let v = vectors();
    let img = image(&v);
    let (w, h) = (img.width, img.height);
    let g = to_gray(&img);
    assert_eq!(fnv(&g.data), v["gray"].as_str().unwrap(), "gray");
    assert_eq!(fnv(&blur2(&g, 2).data), v["blur2r2"].as_str().unwrap(), "blur2");
    assert_eq!(fnv(&sobel(&g).data), v["sobel"].as_str().unwrap(), "sobel");
    assert_eq!(fnv(&color_sobel(&img, 1).data), v["colorSobel"].as_str().unwrap(), "colorSobel");
    assert_eq!(otsu(&g) as i64, v["otsu"].as_i64().unwrap(), "otsu");
    assert_eq!(percentile_threshold(&sobel(&g), 0.1, 20) as i64, v["percentile"].as_i64().unwrap());
    let fg = foreground_from_border(&img, 1);
    assert_eq!(fg.threshold as i64, v["foreground"]["threshold"].as_i64().unwrap(), "fg threshold");
    assert!((fg.separation - v["foreground"]["separation"].as_f64().unwrap()).abs() < 1e-3, "fg separation");
    assert_eq!(fnv(&fg.dist.data), v["foreground"]["dist"].as_str().unwrap(), "fg dist");
    assert_eq!(fnv(&fg.mask), v["foreground"]["mask"].as_str().unwrap(), "fg mask");
    let m = clean_mask(&fg.mask, w, h);
    assert_eq!(fnv(&m), v["foreground"]["clean"].as_str().unwrap(), "clean mask");
    let (labels, comps) = label_components(&m, w, h);
    let got: Vec<Vec<i64>> = comps.iter().map(|c| vec![c.label as i64, c.area as i64, c.min_x as i64, c.min_y as i64, c.max_x as i64, c.max_y as i64]).collect();
    let want: Vec<Vec<i64>> = serde_json::from_value(v["components"].clone()).unwrap();
    assert_eq!(got, want, "components");
    let big = comps.iter().max_by(|a, b| a.area.cmp(&b.area).then(b.label.cmp(&a.label))).unwrap();
    let trace = trace_boundary(&labels, w, h, big.label, big.start_x, big.start_y);
    let want_trace: Vec<[i64; 2]> = serde_json::from_value(v["trace"].clone()).unwrap();
    assert_eq!(trace, want_trace, "trace");
    let tf: Vec<[f64; 2]> = trace.iter().map(|p| [p[0] as f64, p[1] as f64]).collect();
    let want_dp: Vec<[f64; 2]> = serde_json::from_value(v["douglasPeucker"].clone()).unwrap();
    assert_eq!(douglas_peucker(&tf, 1.5, true), want_dp, "dp");
    assert_eq!(fnv(&posterize_levels(&blur2(&g, 2), 4)), v["posterize4"].as_str().unwrap());
    assert_eq!(fnv(&resize_box(&img, 17, 11).data), v["resize"].as_str().unwrap(), "resize");
    let prep = Prep { crop: CropRect { x: 0.1, y: 0.05, w: 0.8, h: 0.9 }, rotation: 90, flip_h: true, brightness: 10.0, contrast: 15.0, difficulty: "intermediate".into(), ..Default::default() };
    let p = prepare_image(&img, &prep.image(), 30);
    assert_eq!((p.width as u64, p.height as u64), (v["prepared"]["width"].as_u64().unwrap(), v["prepared"]["height"].as_u64().unwrap()));
    assert_eq!(fnv(&p.data), v["prepared"]["hash"].as_str().unwrap(), "prepared");
}

#[test]
fn renders_match_js() {
    let v = vectors();
    let img = image(&v);
    let sh = shared();
    for s in &sh.styles.styles {
        let out = render_style(&img, &s.id, &RenderOptions {
            level: sh.level("intermediate"), analysis_max_dim: 320, line_thickness: 2.0, sketch_contrast: 20.0,
            simplify_background: s.id == "pencil_sketch", keep_boxes: None,
        }).unwrap();
        assert_eq!(fnv(&out.data), v["renders"][&s.id].as_str().unwrap(), "render {}", s.id);
    }
}

#[test]
fn geometry_matches_js() {
    let v = vectors();
    let h = homography(&[[0.0, 0.0], [10.0, 0.0], [10.0, 10.0], [0.0, 10.0]], &[[1.0, 2.0], [12.0, 1.0], [11.0, 13.0], [0.0, 9.0]]).unwrap();
    close(&serde_json::to_value(h.to_vec()).unwrap(), &v["homography"], "homography");
    let (w, hh) = (48usize, 36usize);
    let mut g = Gray::new(w, hh);
    for y in 0..hh {
        for x in 0..w {
            let inside = x > 8 && x < 40 && y > 4 && y < 32 && (x as f64 - 8.0) > (y as f64 - 4.0) / 4.0;
            g.data[y * w + x] = if inside { 235 } else { 40 };
        }
    }
    let p = detect_paper(&g).unwrap();
    close(&serde_json::to_value(&p).unwrap(), &v["paper"], "paper");
    assert_eq!(fnv(&warp_gray(&g, &p.corners, 20, 16).data), v["warp"].as_str().unwrap(), "warp");
}

#[test]
fn analysis_and_steps_match_js() {
    let v = vectors();
    let img = image(&v);
    let sh = shared();
    let a = analyze(&img, sh.level("intermediate"), &AnalyzeOptions::default());
    close(&serde_json::to_value(&a).unwrap(), &v["analysis"], "analysis");
    // Steps are generated from the JS analysis to isolate step logic from float noise.
    let ja: Analysis = serde_json::from_value(v["analysis"].clone()).unwrap();
    let prep = Prep { difficulty: "intermediate".into(), ..Default::default() };
    let steps = generate_steps(&ja, &prep, sh);
    let want: Vec<Step> = serde_json::from_value(v["steps"].clone()).unwrap();
    assert_eq!(steps.len(), want.len());
    for (s, w) in steps.iter().zip(&want) {
        assert_eq!(s, w, "step {}", w.id);
    }
}
